using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;

namespace FlowOfficeLab;

public sealed partial class PdfReaderView
{
    readonly Stack<List<Bookmark>> bookmarkUndo=new(),bookmarkRedo=new();
    List<Bookmark>? bookmarkClipboard;
    bool saving,copying;
    Task bookmarkAppearanceTask=Task.CompletedTask;
    Point contextPosition;
    readonly ContextMenu mainMenu=new(),navigationMenu=new();
    Guid? pointerSelectedBookmark;
    static readonly (string Name,string Hex)[] BookmarkColors={ ("红色","#D94262"),("橙色","#C76D18"),("绿色","#27855D"),("蓝色","#326DD1"),("紫色","#8151C8") };
    bool CanEditDocument=>currentFile!=""&&!opening&&!saving&&!readOnlyProbe&&bookmarkAppearanceTask.IsCompleted;
    Bookmark? SelectedBookmark=>navigation.List.SelectedItem as Bookmark;

    void InitializeBookmarkCommands(Grid body,Grid pageHost){
        pageHost.AllowDrop=true;pageHost.DragOver+=(_,e)=>{if(e.Data.GetDataPresent(DataFormats.FileDrop)){e.Effects=DragDropEffects.Copy;return;}if(!CanEditDocument||displayedPage!=currentPage||!e.Data.GetDataPresent(typeof(BookmarkDrag))){e.Effects=DragDropEffects.None;return;}e.Effects=DragDropEffects.Move;e.Handled=true;var p=e.GetPosition(pageImage);DrawSelection(new(0,p.Y),new(pageImage.Width,p.Y+2));selection.Visibility=Visibility.Visible;};
        pageHost.DragLeave+=(_,_)=>selection.Visibility=Visibility.Collapsed;
        pageHost.Drop+=async(_,e)=>{if(e.Data.GetDataPresent(DataFormats.FileDrop))return;selection.Visibility=Visibility.Collapsed;e.Handled=true;if(!CanEditDocument||displayedPage!=currentPage||e.Data.GetData(typeof(BookmarkDrag)) is not BookmarkDrag drag)return;var p=e.GetPosition(pageImage);var normalized=new Point(Math.Clamp(p.X/pageImage.ActualWidth,0,1),Math.Clamp(p.Y/pageImage.ActualHeight,0,1));if(drag.Id==Guid.Empty)await CreateBookmark(normalized,null,"root",drag.Color);else{var bookmark=bookmarks.FirstOrDefault(b=>b.Id==drag.Id);if(bookmark!=null)await UpdateBookmarkDestination(bookmark,normalized);}};
        navigation.ContextMenu=navigationMenu;navigation.List.ContextMenu=navigationMenu;
        navigation.List.PreviewMouseRightButtonDown+=(_,e)=>{DependencyObject? node=e.OriginalSource as DependencyObject;while(node!=null&&node is not ListBoxItem)node=node is Visual?VisualTreeHelper.GetParent(node):LogicalTreeHelper.GetParent(node);updatingNavigation=true;try{navigation.List.SelectedItem=node is ListBoxItem row?row.DataContext:null;}finally{updatingNavigation=false;}};
        navigation.List.PreviewMouseLeftButtonDown+=(_,_)=>pointerSelectedBookmark=SelectedBookmark?.Id;
        navigation.List.PreviewMouseLeftButtonUp+=async(_,e)=>{DependencyObject? node=e.OriginalSource as DependencyObject;while(node!=null&&node is not ListBoxItem){if(node is Button)return;node=node is Visual?VisualTreeHelper.GetParent(node):LogicalTreeHelper.GetParent(node);}if(node is ListBoxItem row&&row.DataContext is Bookmark b&&b.Id==pointerSelectedBookmark){e.Handled=true;await GoToBookmark(b);}};
        navigationMenu.Opened+=(_,_)=>{navigationMenu.Items.Clear();var built=BuildBookmarkMenu(SelectedBookmark);while(built.Items.Count>0){var item=built.Items[0];built.Items.RemoveAt(0);navigationMenu.Items.Add(item);}};
        navigation.ExpansionChanged+=()=>{if(currentFile=="")return;engine.SetBookmarks(bookmarks,false);UpdateTagDisplays();};
        scroll.ContextMenu=mainMenu;scroll.PreviewMouseRightButtonDown+=(_,e)=>{var p=e.GetPosition(pageImage);contextPosition=displayedPage==currentPage&&p.X>=0&&p.Y>=0&&p.X<pageImage.ActualWidth&&p.Y<pageImage.ActualHeight?new(p.X/pageImage.ActualWidth,p.Y/pageImage.ActualHeight):CurrentReadingPosition();};
        mainMenu.Opened+=(_,_)=>BuildMainMenu();
        navigation.List.PreviewKeyDown+=async(_,e)=>{
            if(annotationTab||SelectedBookmark is not Bookmark b)return;
            if(e.Key==Key.F2){e.Handled=true;await RenameBookmark(b);}else if(e.Key==Key.Delete){e.Handled=true;DeleteBookmark(b);}else if(e.Key==Key.Left){e.Handled=true;if(b.HasChildren&&b.Expanded)navigation.Toggle(b);else{int parent=BookmarkTree.Parent(bookmarks,bookmarks.IndexOf(b));if(parent>=0)SelectBookmark(bookmarks[parent]);}}else if(e.Key==Key.Right){e.Handled=true;if(b.HasChildren&&!b.Expanded)navigation.Toggle(b);else if(b.HasChildren){int i=bookmarks.IndexOf(b);SelectBookmark(bookmarks[i+1]);}}else if(e.Key==Key.Enter){e.Handled=true;await GoToBookmark(b);}
        };
        PreviewKeyDown+=async(_,e)=>{
            if(e.OriginalSource is TextBox)return;
            if(Keyboard.Modifiers.HasFlag(ModifierKeys.Control)&&e.Key==Key.B){e.Handled=true;await CreateBookmark(CurrentReadingPosition(),null,"root");}
            else if(Keyboard.Modifiers.HasFlag(ModifierKeys.Control)&&e.Key==Key.Z){e.Handled=true;UndoBookmarks(false);}
            else if(Keyboard.Modifiers.HasFlag(ModifierKeys.Control)&&e.Key==Key.Y){e.Handled=true;UndoBookmarks(true);}
            else if(Keyboard.Modifiers.HasFlag(ModifierKeys.Control)&&e.Key==Key.C){e.Handled=true;if(Keyboard.Modifiers.HasFlag(ModifierKeys.Shift))CopyImage();else await CopyText(false);}
            else if(e.Key==Key.Escape&&copyRegion!=null){ClearCopySelection();}
        };
    }
    MenuItem Menu(string title,Func<Task> action,bool enabled=true,string? shortcut=null){var item=new MenuItem{Header=title,IsEnabled=enabled,InputGestureText=shortcut??""};item.Click+=async(_,_)=>{try{await action();}catch(OperationCanceledException){}catch(Exception ex){status.Text=ex.Message;}};return item;}
    MenuItem ActionMenu(string title,Action action,bool enabled=true,string? shortcut=null)=>Menu(title,()=>{action();return Task.CompletedTask;},enabled,shortcut);
    ContextMenu BuildBookmarkMenu(Bookmark? bookmark){
        var menu=new ContextMenu{FontFamily=FontFamily};bool edit=CanEditDocument;int index=bookmark==null?-1:bookmarks.IndexOf(bookmark);
        menu.Items.Add(Menu("添加顶层书签…",()=>CreateBookmark(CurrentReadingPosition(),null,"root"),edit,"Ctrl+B"));
        if(bookmark!=null){
            menu.Items.Add(Menu("在后面添加同级书签…",()=>CreateBookmark(CurrentReadingPosition(),bookmark,"sibling"),edit));menu.Items.Add(Menu("添加子书签…",()=>CreateBookmark(CurrentReadingPosition(),bookmark,"child"),edit));menu.Items.Add(new Separator());
            menu.Items.Add(Menu("跳转到书签",()=>GoToBookmark(bookmark),bookmark.CanNavigate));menu.Items.Add(Menu("重命名…",()=>RenameBookmark(bookmark),edit,"F2"));menu.Items.Add(Menu("书签属性／位置偏移…",()=>EditBookmark(bookmark),edit));menu.Items.Add(Menu("更新为当前阅读位置",()=>UpdateBookmarkDestination(bookmark,CurrentReadingPosition()),edit));
            var color=new MenuItem{Header="书签颜色",IsEnabled=edit};color.Items.Add(ActionMenu("默认颜色",()=>ChangeBookmarkColor(bookmark,null)));foreach(var c in BookmarkColors){var option=ActionMenu(c.Name,()=>ChangeBookmarkColor(bookmark,c.Hex));option.Icon=new Border{Width=12,Height=12,CornerRadius=new(3),Background=new SolidColorBrush((Color)ColorConverter.ConvertFromString(c.Hex))};color.Items.Add(option);}color.Items.Add(Menu("自定义颜色…",()=>EditBookmark(bookmark)));menu.Items.Add(color);
            menu.Items.Add(ActionMenu(bookmark.Bold?"取消加粗":"加粗",()=>ChangeBookmarks(()=>bookmark.Bold=!bookmark.Bold,bookmark),edit));
            menu.Items.Add(new Separator());menu.Items.Add(ActionMenu("上移",()=>MoveBookmark(bookmark,-1),edit&&index>=0&&BookmarkTree.PreviousSibling(bookmarks,index)>=0));menu.Items.Add(ActionMenu("下移",()=>MoveBookmark(bookmark,1),edit&&index>=0&&BookmarkTree.NextSibling(bookmarks,index)>=0));menu.Items.Add(ActionMenu("缩进为上一个书签的子项",()=>IndentBookmark(bookmark),edit&&index>=0&&BookmarkTree.PreviousSibling(bookmarks,index)>=0));menu.Items.Add(ActionMenu("提升一级",()=>OutdentBookmark(bookmark),edit&&bookmark.Depth>0));
            menu.Items.Add(ActionMenu("复制书签及子项",()=>CopyBookmark(bookmark,false),edit));menu.Items.Add(ActionMenu("剪切书签及子项",()=>CopyBookmark(bookmark,true),edit));menu.Items.Add(ActionMenu("粘贴为子书签",()=>PasteBookmarks(bookmark,true),edit&&bookmarkClipboard!=null));menu.Items.Add(ActionMenu("粘贴到后面",()=>PasteBookmarks(bookmark,false),edit&&bookmarkClipboard!=null));
            if(bookmark.HasChildren){menu.Items.Add(new Separator());menu.Items.Add(ActionMenu(bookmark.Expanded?"折叠此书签":"展开此书签",()=>navigation.Toggle(bookmark)));menu.Items.Add(ActionMenu("展开此分支的全部层级",()=>navigation.ExpandBranch(bookmark,true)));menu.Items.Add(ActionMenu("折叠此分支的全部层级",()=>navigation.ExpandBranch(bookmark,false)));}
            menu.Items.Add(new Separator());menu.Items.Add(ActionMenu(bookmark.HasChildren?"删除书签及子项…":"删除书签",()=>DeleteBookmark(bookmark),edit,"Delete"));if(bookmark.HasChildren)menu.Items.Add(ActionMenu("仅删除此书签，保留子项",()=>DeleteBookmark(bookmark,true),edit));
        }else menu.Items.Add(ActionMenu("粘贴为顶层书签",()=>PasteBookmarks(null,false),edit&&bookmarkClipboard!=null));
        menu.Items.Add(new Separator());menu.Items.Add(Menu("按最高层书签打标",TagTopLevelBookmarks,edit&&bookmarks.Count>0));menu.Items.Add(ActionMenu("展开全部书签",()=>navigation.ExpandAll(true),bookmarks.Count>0));menu.Items.Add(ActionMenu("折叠全部书签",()=>navigation.ExpandAll(false),bookmarks.Count>0));menu.Items.Add(ActionMenu("撤销书签修改",()=>UndoBookmarks(false),edit&&bookmarkUndo.Count>0,"Ctrl+Z"));menu.Items.Add(ActionMenu("重做书签修改",()=>UndoBookmarks(true),edit&&bookmarkRedo.Count>0,"Ctrl+Y"));return menu;
    }
    void BuildMainMenu(){
        mainMenu.Items.Clear();bool usable=currentFile!=""&&!opening&&displayedPage==currentPage;
        mainMenu.Items.Add(Menu("添加彩色标签…",()=>AddPageTag(contextPosition),CanEditDocument&&usable));mainMenu.Items.Add(Menu("在此处添加书签…",()=>CreateBookmark(contextPosition,null,"root"),CanEditDocument&&usable));mainMenu.Items.Add(Menu("在所选书签下添加子书签…",()=>CreateBookmark(contextPosition,SelectedBookmark,"child"),CanEditDocument&&usable&&SelectedBookmark!=null));
        mainMenu.Items.Add(Menu("在此处插入批注…",async()=>{if(!CanEditDocument)return;var text=InputNote();if(text!=null)await AddAnnotation(contextPosition,contextPosition,false,text);},CanEditDocument&&usable));mainMenu.Items.Add(ActionMenu("文字高亮",()=>SetMode(1),CanEditDocument&&usable));mainMenu.Items.Add(new Separator());
        mainMenu.Items.Add(ActionMenu("框选悬停预览来源",()=>SetMode(4),CanEditDocument&&usable));mainMenu.Items.Add(Menu("在此处放置悬停标…",PlaceHoverMark,CanEditDocument&&usable&&pendingHoverSource!=null));mainMenu.Items.Add(ActionMenu("清除已选悬停来源",()=>pendingHoverSource=null,pendingHoverSource!=null));mainMenu.Items.Add(Menu("将选区固定为置顶小窗",()=>PinRegion(currentPage,copyRegion!.Value),usable&&copyRegion!=null));mainMenu.Items.Add(Menu("将整页固定为置顶小窗",()=>PinRegion(currentPage,new Rect(0,0,1,1)),usable));mainMenu.Items.Add(new Separator());
        mainMenu.Items.Add(ActionMenu("选择复制区域",()=>SetMode(3),usable));mainMenu.Items.Add(Menu(copyRegion==null?"复制本页文字（智能合并换行）":"复制选区文字（智能合并换行）",()=>CopyText(false),usable&&!copying,"Ctrl+C"));mainMenu.Items.Add(Menu("复制文字（保留原始换行）",()=>CopyText(true),usable&&!copying));mainMenu.Items.Add(ActionMenu(copyRegion==null?"复制本页图片":"复制选区图片",CopyImage,usable,"Ctrl+Shift+C"));mainMenu.Items.Add(ActionMenu("清除复制选区",ClearCopySelection,copyRegion!=null));mainMenu.Items.Add(ActionMenu("复制当前位置引用",()=>Clipboard.SetText($"{Path.GetFileName(currentFile)} · 第 {currentPage+1} 页"),usable));mainMenu.Items.Add(new Separator());
        mainMenu.Items.Add(Menu("复制此处图片（原图）",CopyEmbeddedImage,usable));
        mainMenu.Items.Add(Menu("识别并复制文字（OCR）",CopyRecognizedText,usable&&!copying));
        mainMenu.Items.Add(Menu("上一页",()=>ShowPage(currentPage-1),usable&&currentPage>0));mainMenu.Items.Add(Menu("下一页",()=>ShowPage(currentPage+1),usable&&currentPage+1<engine.PageCount));mainMenu.Items.Add(Menu("整页适应",()=>SetFit(true),usable));mainMenu.Items.Add(Menu("适宽",()=>SetFit(false),usable));mainMenu.Items.Add(Menu(wheelPageMode?"切换为到页尾自动翻页":"切换为仅页内滚动",()=>SetWheelMode(!wheelPageMode),usable));mainMenu.Items.Add(new Separator());mainMenu.Items.Add(Menu("打开 PDF…",ChooseFile,!saving));mainMenu.Items.Add(Menu("保存",async()=>{await SaveCurrent();},CanEditDocument));mainMenu.Items.Add(Menu("另存副本…",SaveCopy,CanEditDocument));
    }
    Point CurrentReadingPosition(){if(pageImage.ActualHeight<=0)return new(0,0);var origin=pageImage.TranslatePoint(new Point(0,0),scroll);return new(Math.Clamp((16-origin.X)/pageImage.ActualWidth,0,1),Math.Clamp((16-origin.Y)/pageImage.ActualHeight,0,1));}
    void SelectBookmark(Bookmark b){tagTab=false;annotationTab=false;RefreshNavigation();updatingNavigation=true;try{navigation.Reveal(b);navigation.List.SelectedItem=b;navigation.List.ScrollIntoView(b);}finally{updatingNavigation=false;}}
    void RememberBookmarks(){bookmarkUndo.Push(bookmarks.Select(b=>b.Clone()).ToList());bookmarkRedo.Clear();if(bookmarkUndo.Count>40){var keep=bookmarkUndo.Take(40).Reverse().ToArray();bookmarkUndo.Clear();foreach(var snapshot in keep)bookmarkUndo.Push(snapshot);}}
    void ChangeBookmarks(Action mutation,Bookmark? selected=null){if(!CanEditDocument)return;var styles=bookmarks.ToDictionary(b=>b.Id,b=>(b.ColorHex,b.Bold,b.Italic));RememberBookmarks();mutation();foreach(var b in bookmarks)if(styles.TryGetValue(b.Id,out var before)){b.ColorEdited|=b.ColorHex!=before.ColorHex;b.StyleEdited|=b.Bold!=before.Bold||b.Italic!=before.Italic;}BookmarksChanged(selected);}
    void BookmarksChanged(Bookmark? selected=null){BookmarkTree.Normalize(bookmarks);engine.SetBookmarks(bookmarks);RefreshNavigation();UpdateTagDisplays();if(selected!=null&&bookmarks.Contains(selected))SelectBookmark(selected);status.Text="书签已修改，记得保存";Host.ReaderChanged(this);}
    async Task ReadBookmarkAppearance(string path,CancellationToken token,int documentGeneration){
        try{var metadata=await PdfOutlineStore.ReadMetadataAsync(path,token);var appearance=metadata.Outlines;if(token.IsCancellationRequested||generation!=documentGeneration)return;pageTags.Clear();pageTags.AddRange(metadata.Tags);engine.SetPageTags(pageTags,false);foreach(var style in appearance){var b=bookmarks.FirstOrDefault(b=>b.SourceIndex==style.Index);if(b==null)continue;b.ColorHex=style.Color;b.Bold=style.Bold;b.Italic=style.Italic;b.PresentationLoaded=true;if(b.ColorHex!=null&&b.CanNavigate){var position=await engine.LocateBookmarkAsync(b,token);if(position!=null)b.VisualY=position.Value.Y;}}if(generation==documentGeneration){RefreshNavigation();UpdateTagDisplays();if(TagWidth(currentPage)>0)await ShowPage(currentPage,false,true,true);}}catch(OperationCanceledException){}catch(Exception ex){if(generation==documentGeneration)status.Text="书签颜色读取失败："+ex.Message;}
    }
    async Task CreateBookmark(Point position,Bookmark? relative,string placement,string? color=null){
        if(!CanEditDocument)return;int doc=generation;var draft=new Bookmark($"第 {currentPage+1} 页",currentPage,placement=="child"&&relative!=null?relative.Depth+1:relative?.Depth??0){ColorHex=color};var dialog=new BookmarkDialog(Host,draft,engine.PageCount,position,true);if(dialog.ShowDialog()!=true||dialog.Result==null)return;var edit=dialog.Result;var point=await engine.PagePointAsync(edit.Page,new(edit.Horizontal,edit.Vertical),documentCancellation.Token);if(doc!=generation||!CanEditDocument)return;
        draft.Title=edit.Title;draft.Page=edit.Page;draft.X=point.X;draft.Y=point.Y;draft.VisualY=edit.Vertical;draft.ColorHex=edit.Color;draft.Bold=edit.Bold;draft.Italic=edit.Italic;draft.DestinationEdited=true;ChangeBookmarks(()=>{int i=relative==null?bookmarks.Count:BookmarkTree.End(bookmarks,bookmarks.IndexOf(relative));bookmarks.Insert(i,draft);if(relative!=null&&placement=="child")relative.Expanded=true;},draft);
    }
    async Task EditBookmark(Bookmark bookmark){
        if(!CanEditDocument)return;int doc=generation;var position=bookmark.CanNavigate?await engine.LocateBookmarkAsync(bookmark,documentCancellation.Token):null;var dialog=new BookmarkDialog(Host,bookmark,engine.PageCount,position??new Point(0,0),false);if(dialog.ShowDialog()!=true||dialog.Result==null)return;var edit=dialog.Result;Point? pdfPoint=edit.ChangeDestination?await engine.PagePointAsync(edit.Page,new(edit.Horizontal,edit.Vertical),documentCancellation.Token):null;if(doc!=generation||!CanEditDocument)return;ChangeBookmarks(()=>{bookmark.Title=edit.Title;bookmark.ColorHex=edit.Color;bookmark.Bold=edit.Bold;bookmark.Italic=edit.Italic;if(pdfPoint!=null){bookmark.Page=edit.Page;bookmark.X=pdfPoint.Value.X;bookmark.Y=pdfPoint.Value.Y;bookmark.VisualY=edit.Vertical;bookmark.DestinationEdited=true;}},bookmark);
    }
    Task RenameBookmark(Bookmark bookmark){if(!CanEditDocument)return Task.CompletedTask;var title=InputText("重命名书签",bookmark.Title);if(!string.IsNullOrWhiteSpace(title)&&title.Trim()!=bookmark.Title)ChangeBookmarks(()=>bookmark.Title=title.Trim(),bookmark);return Task.CompletedTask;}
    string? InputText(string title,string value){var dialog=new Window{Owner=Host,Title=title,Width=420,Height=155,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,FontFamily=FontFamily};var panel=new StackPanel{Margin=new(18)};var input=new TextBox{Text=value,Padding=new(8,5,8,5)};panel.Children.Add(input);var buttons=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new(0,12,0,0)};var cancel=new Button{Content="取消",IsCancel=true};var ok=new Button{Content="保存",IsDefault=true};ok.Click+=(_,_)=>{if(!string.IsNullOrWhiteSpace(input.Text))dialog.DialogResult=true;};buttons.Children.Add(cancel);buttons.Children.Add(ok);panel.Children.Add(buttons);dialog.Content=panel;dialog.Loaded+=(_,_)=>{input.Focus();input.SelectAll();};return dialog.ShowDialog()==true?input.Text:null;}
    async Task UpdateBookmarkDestination(Bookmark b,Point position){if(!CanEditDocument)return;int doc=generation,page=currentPage;var p=await engine.PagePointAsync(page,position,documentCancellation.Token);if(doc!=generation||!CanEditDocument)return;ChangeBookmarks(()=>{b.Page=page;b.X=p.X;b.Y=p.Y;b.VisualY=position.Y;b.DestinationEdited=true;},b);}
    void ChangeBookmarkColor(Bookmark b,string? color)=>ChangeBookmarks(()=>{b.ColorHex=color;b.PresentationLoaded=true;},b);
    void DeleteBookmark(Bookmark b,bool keepChildren=false){if(!CanEditDocument)return;int i=bookmarks.IndexOf(b),end=BookmarkTree.End(bookmarks,i);if(!keepChildren&&end>i+1&&MessageBox.Show(Host,$"删除“{b.Title}”及其 {end-i-1} 个子书签？可以撤销。","删除书签",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;ChangeBookmarks(()=>{if(keepChildren){for(int j=i+1;j<end;j++)bookmarks[j].Depth--;bookmarks.RemoveAt(i);}else bookmarks.RemoveRange(i,end-i);});}
    void MoveBookmark(Bookmark b,int direction){int i=bookmarks.IndexOf(b),end=BookmarkTree.End(bookmarks,i),target=direction<0?BookmarkTree.PreviousSibling(bookmarks,i):BookmarkTree.NextSibling(bookmarks,i);if(target<0)return;int destination=direction<0?target:BookmarkTree.End(bookmarks,target)-(end-i);ChangeBookmarks(()=>{var branch=bookmarks.GetRange(i,end-i);bookmarks.RemoveRange(i,end-i);bookmarks.InsertRange(destination,branch);},b);}
    void IndentBookmark(Bookmark b){int i=bookmarks.IndexOf(b),previous=BookmarkTree.PreviousSibling(bookmarks,i);if(previous<0)return;int end=BookmarkTree.End(bookmarks,i);ChangeBookmarks(()=>{for(int j=i;j<end;j++)bookmarks[j].Depth++;bookmarks[previous].Expanded=true;},b);}
    void OutdentBookmark(Bookmark b){int i=bookmarks.IndexOf(b),parent=BookmarkTree.Parent(bookmarks,i);if(parent<0)return;int end=BookmarkTree.End(bookmarks,i),parentEnd=BookmarkTree.End(bookmarks,parent);ChangeBookmarks(()=>{var branch=bookmarks.GetRange(i,end-i);bookmarks.RemoveRange(i,end-i);foreach(var item in branch)item.Depth--;bookmarks.InsertRange(parentEnd-(end-i),branch);},b);}
    void CopyBookmark(Bookmark b,bool cut){int i=bookmarks.IndexOf(b),end=BookmarkTree.End(bookmarks,i);bookmarkClipboard=bookmarks.GetRange(i,end-i).Select(x=>x.Clone()).ToList();if(cut)ChangeBookmarks(()=>bookmarks.RemoveRange(i,end-i));status.Text=cut?"书签已剪切，可以粘贴到其他层级":"书签及子项已复制";}
    void PasteBookmarks(Bookmark? parent,bool child){if(bookmarkClipboard==null)return;var branch=bookmarkClipboard.Select(b=>b.Clone(true)).ToList();int depth=parent==null?0:parent.Depth+(child?1:0),delta=depth-branch[0].Depth;foreach(var b in branch)b.Depth+=delta;ChangeBookmarks(()=>{int i=parent==null?bookmarks.Count:BookmarkTree.End(bookmarks,bookmarks.IndexOf(parent));bookmarks.InsertRange(i,branch);if(parent!=null&&child)parent.Expanded=true;},branch[0]);}
    void UndoBookmarks(bool redo){if(!CanEditDocument)return;var from=redo?bookmarkRedo:bookmarkUndo;var to=redo?bookmarkUndo:bookmarkRedo;if(from.Count==0)return;var selected=SelectedBookmark?.Id;to.Push(bookmarks.Select(b=>b.Clone()).ToList());bookmarks.Clear();bookmarks.AddRange(from.Pop());BookmarksChanged(bookmarks.FirstOrDefault(b=>b.Id==selected));status.Text=redo?"已重做书签修改":"已撤销书签修改";}
}
